package app.trycommish.core

/**
 * The app's own words: what the web has no word table for, because the web has no such screen part
 * (the answer kept on the phone, a lapsed sign-in, a read that failed with nothing kept) or prints the
 * word inside a component. The web's words are Words (app.trycommish.design, generated by
 * shared/scripts/gen-words.ts); the copy guard (app/src/test CopyGuardTest) reads both.
 */
@Suppress("ktlint:standard:property-naming") // Word tables read like Words.LeagueHome.
object AppWords {
    /** The stamp of an answer read, and of one kept from before while the API cannot be reached. */
    const val read = "Read"
    const val offline = "No connection, showing the read of"

    /** A member with no league attached yet: where to attach one. */
    const val noLeague = "Attach a league from ESPN, Sleeper, Yahoo, MyFantasyLeague or FFPC at trycommish.app, then pull down here."

    /** With nothing kept and no connection: what happened and what to do, never an error code. */
    const val cannotLoad = "We could not reach Commish. Check your connection, then pull down to try again."

    /** The way to read again from a screen that has nothing to show. */
    const val tryAgain = "Try again"

    /** The API no longer takes the device's sign-in (it lapsed unused, or was revoked). */
    const val signedOut = "Your sign-in on this phone has run out. Sign in again to see your leagues."

    /** A platform this build does not know yet (an API newer than the app). */
    const val unknownPlatform = "your platform"

    /** A traded player's new team, "to Dad Runners" (web/src/lib/league/home/MovesFeed.svelte). */
    const val to = "to"

    /** The league switch opened with no league followed: where to follow one (the iOS app's words). */
    const val followNone = "Follow a league on trycommish.app and it shows here."

    /** The Players screen's name (nav.ts PLAYERS_NAME), which the bar's search and a player's link open. */
    const val players = "Players"

    /** web/src/lib/league/LeaguePage.svelte stampOf: a read whose latest try failed, "Last read Sat 12:00 pm". */
    const val lastRead = "Last read"

    /** Under the Start screen's verb, disabled, while the lineup shown is a saved read (the iOS app's
     * words): a lineup set from it may not be the platform's now, so the phone reads it again first. */
    const val readAgainToSet = "Pull down to read your lineup again before you set it."

    /** Under the Waivers screen's verb, disabled, while the waivers shown are a saved read (the iOS app's
     * words): a player on it may have been claimed since, so the phone reads them again first. */
    fun waiversStale(stamp: String): String = "$stamp. Pull down to read waivers again before you claim."

    /** The board's nouns as the bar names it (web nav.ts), the iOS AppWords.Tab's: the draft's board, and
     * in season the board of the rest of the season. */
    const val board = "Board"
    const val restOfSeason = "Rest of season"

    /** The record page's name as the bar names it (web nav.ts), the iOS AppWords.Tab.record. */
    const val record = "Our record"

    /** site/offline-words.ts offlineLead, before the run's day: why a saved board shows with no signal. */
    const val offlineBoard = "You're offline, so this is the last board this device saved, updated"
}
